import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import client from '../api/client';
import toast from 'react-hot-toast';

export const useAdminUserDashboard = (userId) => {
    const navigate = useNavigate();
    const [user, setUser] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    const [formLoading, setFormLoading] = useState(false);
    const [parentChildren, setParentChildren] = useState([]);
    const [connectionCode, setConnectionCode] = useState(null);
    const [allUsers, setAllUsers] = useState([]);

    // Inline forms/views state
    const [showNewPassword, setShowNewPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [childSearchQuery, setChildSearchQuery] = useState('');
    const [studentParents, setStudentParents] = useState([]);
    const [parentSearchQuery, setParentSearchQuery] = useState('');

    // Assign project state
    const [templates, setTemplates] = useState({});
    const [selectedTemplateName, setSelectedTemplateName] = useState('');
    const [templatesSaving, setTemplatesSaving] = useState(false);

    // Pass chapter state
    const [passChapterLoading, setPassChapterLoading] = useState(false);
    const [selectedChapterId, setSelectedChapterId] = useState('');
    const [passPreview, setPassPreview] = useState(null);

    const fetchUser = async () => {
        setIsLoading(true);
        try {
            const res = await client.get(`/api/admin/user/${userId}`);
            const fetchedUser = res.data.user;
            setUser(fetchedUser);
        } catch {
            toast.error('Failed to load user details.');
            navigate('/admin/users');
        } finally {
            setIsLoading(false);
        }
    };

    const fetchAllUsers = async () => {
        try {
            const res = await client.get(`/api/admin/users?per_page=1000`);
            setAllUsers(res.data.users || []);
        } catch (err) {
            console.error("Failed to fetch all users for parent dropdown", err);
        }
    };

    const fetchTemplates = async () => {
        try {
            const response = await client.get('/api/project-templates');
            if (response.data?.data?.templates) {
                setTemplates(response.data.data.templates);
            }
        } catch {
            toast.error('Failed to load project templates.');
        }
    };

    const handlePassChapterPreview = async (e) => {
        e.preventDefault();
        setPassChapterLoading(true);
        try {
            const res = await client.post(`/api/admin/user/${userId}/pass_chapter_preview`, { course_id: selectedChapterId });
            if (res.data.success) {
                setPassPreview(res.data.preview);
            }
        } catch {
            toast.error('Failed to preview chapter pass');
        } finally {
            setPassChapterLoading(false);
        }
    };

    const handlePassChapterConfirm = async () => {
        if (!window.confirm("Are you sure you want to pass this chapter? They will receive all achievements, certificates, and ducks.")) {
            return;
        }
        setPassChapterLoading(true);
        try {
            const res = await client.post(`/api/admin/user/${userId}/pass_chapter`, { course_id: selectedChapterId });
            if (res.data.success) {
                toast.success(res.data.message);
                setPassPreview(null);
                setSelectedChapterId('');
                fetchUser();
            }
        } catch {
            toast.error('Failed to pass chapter');
        } finally {
            setPassChapterLoading(false);
        }
    };

    const handleAdjustDucks = async (e) => {
        e.preventDefault();
        setFormLoading(true);
        const formData = new FormData(e.target);
        
        try {
            const res = await client.post('/api/admin/adjust_ducks', formData);
            if (res.data.success) {
                toast.success(res.data.message);
                e.target.reset();
                fetchUser();
            } else {
                toast.error(res.data.message || "Failed to adjust ducks");
            }
        } catch (err) {
            toast.error(err.response?.data?.error || 'An error occurred.');
        } finally {
            setFormLoading(false);
        }
    };

    const handleAdjustPackets = async (e) => {
        e.preventDefault();
        setFormLoading(true);
        const formData = new FormData(e.target);
        
        try {
            const res = await client.post('/api/admin/adjust_packets', formData);
            if (res.data.success) {
                toast.success(res.data.message);
                e.target.reset();
                fetchUser();
            } else {
                toast.error(res.data.message || "Failed to adjust packets");
            }
        } catch (err) {
            toast.error(err.response?.data?.error || 'An error occurred.');
        } finally {
            setFormLoading(false);
        }
    };

    const handleSetDrawer = async (e) => {
        e.preventDefault();
        setFormLoading(true);
        const formData = new FormData(e.target);
        formData.append('username', user.username);
        
        try {
            const res = await client.post('/api/admin/set_drawer', formData);
            if (res.status === 200) {
                toast.success(res.data.message || 'Drawer updated');
                fetchUser();
            }
        } catch (err) {
            toast.error(err.response?.data || 'Failed to update drawer');
        } finally {
            setFormLoading(false);
        }
    };

    const handleResetPassword = async (e) => {
        e.preventDefault();
        setFormLoading(true);
        const formData = new FormData(e.target);
        
        try {
            const res = await client.post('/api/admin/reset_password', formData);
            if (res.data.success) {
                toast.success(res.data.message);
                e.target.reset();
            } else {
                toast.error(res.data.message || "Failed to reset password");
            }
        } catch (err) {
            toast.error(err.response?.data?.error || 'An error occurred.');
        } finally {
            setFormLoading(false);
        }
    };

    const handleRemoveUser = async () => {
        if (!window.confirm(`Are you sure you want to completely remove ${user.username}? This cannot be undone.`)) {
            return;
        }
        try {
            const formData = new FormData();
            formData.append('username', user.username);
            const res = await client.post('/api/admin/remove_user', formData);
            if (res.data.success) {
                toast.success(res.data.message);
                navigate('/admin/users');
            } else {
                toast.error(res.data.message || "Failed to remove user");
            }
        } catch (err) {
            toast.error(err.response?.data?.error || 'An error occurred.');
        }
    };

    const handleApproveUser = async () => {
        setFormLoading(true);
        try {
            const response = await client.post(`/api/admin/approve_user/${user.id}`);
            if (response.data.status === 'success') {
                toast.success(response.data.data.message);
                fetchUser();
            }
        } catch {
            toast.error('Failed to approve user.');
        } finally {
            setFormLoading(false);
        }
    };

    const handleRejectUser = async () => {
        if (!window.confirm('Are you sure you want to reject and delete this user?')) return;
        setFormLoading(true);
        try {
            const response = await client.post(`/api/admin/reject_user/${user.id}`);
            if (response.data.status === 'success') {
                toast.success(response.data.data.message);
                navigate('/admin/users');
            }
        } catch {
            toast.error('Failed to reject user.');
        } finally {
            setFormLoading(false);
        }
    };

    const fetchParentChildren = async () => {
        try {
            const response = await client.get(`/api/admin/parents/${user.id}/children`);
            if (response.data.success) {
                setParentChildren(response.data.children);
            }
        } catch {
            toast.error('Failed to fetch parent children');
        }
    };

    const handleToggleChildLink = async (childId, isLinked) => {
        setFormLoading(true);
        try {
            const endpoint = isLinked ? 'unlink' : 'link';
            const response = await client.post(`/api/admin/parents/${user.id}/${endpoint}/${childId}`);
            if (response.data.success) {
                toast.success(`Successfully ${isLinked ? 'unlinked' : 'linked'} child account`);
                fetchParentChildren();
            } else {
                toast.error(response.data.message || `Failed to ${endpoint} child`);
            }
        } catch (error) {
            toast.error(error.response?.data?.message || 'An error occurred');
        } finally {
            setFormLoading(false);
        }
    };

    const fetchStudentParents = async () => {
        try {
            const response = await client.get(`/api/admin/students/${userId}/parents`);
            if (response.data.success) {
                setStudentParents(response.data.parents || []);
            }
        } catch {
            toast.error('Failed to fetch student parents');
        }
    };

    const handleToggleParentLink = async (parentId, isLinked) => {
        setFormLoading(true);
        try {
            const endpoint = isLinked ? 'unlink' : 'link';
            const response = await client.post(`/api/admin/parents/${parentId}/${endpoint}/${user.id}`);
            if (response.data.success) {
                toast.success(`Successfully ${isLinked ? 'unlinked' : 'linked'} parent account`);
                fetchStudentParents();
            } else {
                toast.error(response.data.message || `Failed to ${endpoint} parent`);
            }
        } catch (error) {
            toast.error(error.response?.data?.message || 'An error occurred');
        } finally {
            setFormLoading(false);
        }
    };

    const handleAssignProjectSubmit = async (e) => {
        e.preventDefault();
        if (!selectedTemplateName) {
            toast.error('Please select a project template.');
            return;
        }

        setTemplatesSaving(true);
        const template = templates[selectedTemplateName];
        const formData = new FormData();
        formData.append('name', selectedTemplateName);
        formData.append('description', template?.description || '');
        formData.append('student_id', user.id);

        try {
            const response = await client.post('/user/project/new', formData);
            if (response.data.status === 'success') {
                toast.success(`Assigned ${selectedTemplateName} to ${user.nickname || user.username}!`);
                setSelectedTemplateName('');
                fetchUser();
            } else {
                toast.error(response.data.error || 'Failed to assign project.');
            }
        } catch (error) {
            console.error('Assign error:', error);
            toast.error(error.response?.data?.error || 'An error occurred.');
        } finally {
            setTemplatesSaving(false);
        }
    };

    const fetchConnectionCode = async () => {
        try {
            const response = await client.get(`/api/admin/user/${user.id}/connection_card`);
            if (response.data.status === 'success') {
                setConnectionCode(response.data.data.connection_code);
            }
        } catch (error) {
            console.error('Failed to fetch connection code', error);
        }
    };

    useEffect(() => {
        fetchUser();
    }, [userId]);

    useEffect(() => {
        if (user) {
            if (user.role === 'parent') {
                fetchAllUsers();
                fetchParentChildren();
            } else if (user.role === 'student') {
                fetchAllUsers();
                fetchTemplates();
                fetchConnectionCode();
                fetchStudentParents();
            }
        }
    }, [user?.id]);

    const handleUpdateUser = async (updatedFields) => {
        setFormLoading(true);
        try {
            const res = await client.put(`/api/admin/user/${userId}`, updatedFields);
            const responseData = res.data?.data || res.data;
            if (responseData.user || responseData.message) {
                toast.success(responseData.message || 'User profile updated successfully');
                if (responseData.user) {
                    setUser(responseData.user);
                } else {
                    fetchUser();
                }
            } else {
                toast.error(responseData.error || 'Failed to update user profile');
            }
        } catch (err) {
            toast.error(err.response?.data?.error || err.response?.data?.message || 'Failed to update user profile.');
        } finally {
            setFormLoading(false);
        }
    };

    return {
        user, isLoading, formLoading, parentChildren, connectionCode, allUsers,
        showNewPassword, setShowNewPassword, showConfirmPassword, setShowConfirmPassword,
        childSearchQuery, setChildSearchQuery, studentParents, parentSearchQuery, setParentSearchQuery,
        templates, selectedTemplateName, setSelectedTemplateName, templatesSaving,
        passChapterLoading, selectedChapterId, setSelectedChapterId, passPreview, setPassPreview,
        fetchUser, handlePassChapterPreview, handlePassChapterConfirm, handleAdjustDucks,
        handleAdjustPackets, handleSetDrawer, handleResetPassword, handleRemoveUser,
        handleApproveUser, handleRejectUser, handleToggleChildLink, handleToggleParentLink,
        handleAssignProjectSubmit, handleUpdateUser
    };
};

import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import client from '../../api/client';
import toast from 'react-hot-toast';
import { 
    ChevronLeft, Users, RefreshCw, Trash2, 
    Check, Plus, Settings, Globe, Link2, BookOpen
} from 'lucide-react';
import AdminPageHeader from '../../components/admin/AdminPageHeader';
import Chat from '../Chat/Chat';
import Skeleton from '../../components/common/Skeleton';
import SmartImage from '../../components/common/SmartImage';
import { getApiUrl } from '../../utils/apiUrl';
import { BulkConnectionCardsModal } from '../../components/admin/AdminModals';
import './AdminClassDashboard.css';

const getLanguageIconUrl = (language) => {
    const lang = (language || '').toLowerCase();
    if (lang.includes('python')) return "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/python/python-original.svg";
    if (lang.includes('javascript') || lang.includes('js')) return "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/javascript/javascript-original.svg";
    if (lang.includes('html') || lang.includes('css')) return "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/html5/html5-original.svg";
    if (lang.includes('java') && !lang.includes('javascript')) return "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/java/java-original.svg";
    if (lang.includes('c++') || lang.includes('cpp')) return "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/cplusplus/cplusplus-original.svg";
    return null;
};

const AdminClassDashboard = () => {
    const { classId } = useParams();
    const navigate = useNavigate();
    const [classroom, setClassroom] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    const [formLoading, setFormLoading] = useState(false);
    const [allStudents, setAllStudents] = useState([]);
    const [selectedStudentId, setSelectedStudentId] = useState('');
    const [rosterSearchQuery, setRosterSearchQuery] = useState('');
    const [activeTab, setActiveTab] = useState('stream');

    // Connection cards states
    const [activeModal, setActiveModal] = useState(null);
    const [classroomCards, setClassroomCards] = useState([]);
    const [isFetchingCards, setIsFetchingCards] = useState(false);

    const fetchClassroomDetails = useCallback(async () => {
        setIsLoading(true);
        try {
            const res = await client.get(`/api/admin/classrooms/${classId}`);
            setClassroom(res.data.classroom);
        } catch (err) {
            console.error('Failed to fetch classroom:', err);
            toast.error('Failed to load classroom details.');
            navigate('/admin/classes');
        } finally {
            setIsLoading(false);
        }
    }, [classId, navigate]);

    const fetchAllStudents = useCallback(async () => {
        try {
            const res = await client.get(`/api/admin/users?per_page=1000`);
            const students = (res.data.users || []).filter(u => u.role === 'student');
            setAllStudents(students);
        } catch (err) {
            console.error('Failed to fetch students list', err);
        }
    }, []);

    useEffect(() => {
        fetchClassroomDetails();
        fetchAllStudents();
    }, [fetchClassroomDetails, fetchAllStudents]);

    const fetchClassroomCards = async () => {
        setIsFetchingCards(true);
        try {
            const response = await client.get(`/api/admin/classrooms/${classId}/connection_cards`);
            setClassroomCards(response.data.data?.cards || response.data.cards || []);
            return true;
        } catch (error) {
            console.error('Error fetching cards:', error);
            toast.error('Failed to load connection cards.');
            setClassroomCards([]);
            return false;
        } finally {
            setIsFetchingCards(false);
        }
    };

    const handleUpdateSettings = async (e) => {
        e.preventDefault();
        setFormLoading(true);
        const formData = new FormData(e.target);
        const data = {
            name: formData.get('name'),
            language: formData.get('language'),
            url: formData.get('url'),
            course_id: formData.get('course_id') || null
        };

        try {
            const res = await client.put(`/api/admin/classrooms/${classId}`, data);
            if (res.data.success) {
                toast.success(res.data.message || 'Classroom updated successfully');
                fetchClassroomDetails();
            }
        } catch (err) {
            toast.error(err.response?.data?.error || 'Failed to update classroom.');
        } finally {
            setFormLoading(false);
        }
    };

    const handleEnrollStudent = async (e) => {
        e.preventDefault();
        if (!selectedStudentId) return;
        setFormLoading(true);
        try {
            const res = await client.post(`/api/admin/classrooms/${classId}/enroll`, {
                student_id: Number(selectedStudentId)
            });
            if (res.data.success) {
                toast.success(res.data.message || 'Student enrolled successfully');
                setSelectedStudentId('');
                fetchClassroomDetails();
            }
        } catch (err) {
            toast.error(err.response?.data?.error || 'Failed to enroll student.');
        } finally {
            setFormLoading(false);
        }
    };

    const handleUnenrollStudent = async (studentId) => {
        if (!window.confirm('Are you sure you want to remove this student from the classroom?')) return;
        setFormLoading(true);
        try {
            const res = await client.post(`/api/admin/classrooms/${classId}/unenroll`, {
                student_id: studentId
            });
            if (res.data.success) {
                toast.success(res.data.message || 'Student removed successfully');
                fetchClassroomDetails();
            }
        } catch (err) {
            toast.error(err.response?.data?.error || 'Failed to unenroll student.');
        } finally {
            setFormLoading(false);
        }
    };

    const handleDeleteClassroom = async () => {
        if (!window.confirm(`WARNING: Are you sure you want to delete classroom "${classroom.name}"? This cannot be undone.`)) {
            return;
        }
        try {
            const res = await client.delete(`/api/admin/classrooms/${classId}`);
            if (res.data.success) {
                toast.success(res.data.message || 'Classroom deleted successfully');
                navigate('/admin/classes');
            }
        } catch (err) {
            toast.error(err.response?.data?.error || 'Failed to delete classroom.');
        }
    };

    if (isLoading) {
        return (
            <div className="admin-class-dashboard">
                <div className="dashboard-header">
                    <Skeleton height="40px" width="300px" className="skeleton-title" />
                </div>
                <div className="dashboard-layout">
                    <div className="main-content">
                        <Skeleton height="300px" className="skeleton-card" />
                    </div>
                </div>
            </div>
        );
    }

    // Filter roster students
    const filteredRoster = (classroom.students || []).filter(student => {
        const query = rosterSearchQuery.toLowerCase();
        return (
            student.username?.toLowerCase().includes(query) ||
            (student.nickname && student.nickname.toLowerCase().includes(query))
        );
    });

    // Determine students available for enrollment (excluding already enrolled)
    const enrolledIds = new Set((classroom.students || []).map(s => s.id));
    const availableStudents = allStudents.filter(s => !enrolledIds.has(s.id));

    return (
        <div className="admin-class-dashboard">
            <div className="back-navigation">
                <button 
                    onClick={() => navigate('/admin/classes')} 
                    className="back-btn-text"
                    aria-label="Back to Classroom Directory"
                >
                    <ChevronLeft size={16} aria-hidden="true" /> Back to Directory
                </button>
            </div>

            <div className="classroom-banner">
                <div className="banner-content">
                    <h1>
                        {classroom.name}
                        {classroom.language && getLanguageIconUrl(classroom.language) ? (
                            <img src={getLanguageIconUrl(classroom.language)} alt={classroom.language} className="banner-lang-icon" />
                        ) : classroom.language && (
                            <span className="banner-lang-badge">{classroom.language}</span>
                        )}
                    </h1>
                </div>
                <div className="banner-actions">
                    <button className="secondary-btn" onClick={async () => { await fetchClassroomCards(); setActiveModal('bulk_connection_cards'); }}>
                        Print Connection Cards
                    </button>
                    <button onClick={fetchClassroomDetails} className="refresh-btn">
                        <RefreshCw size={18} />
                    </button>
                </div>
            </div>

            <div className="classroom-tabs">
                <button className={`tab-btn ${activeTab === 'stream' ? 'active' : ''}`} onClick={() => setActiveTab('stream')}>Stream</button>
                <button className={`tab-btn ${activeTab === 'classwork' ? 'active' : ''}`} onClick={() => setActiveTab('classwork')}>Classwork</button>
                <button className={`tab-btn ${activeTab === 'people' ? 'active' : ''}`} onClick={() => setActiveTab('people')}>People</button>
                <button className={`tab-btn ${activeTab === 'settings' ? 'active' : ''}`} onClick={() => setActiveTab('settings')}>Settings</button>
            </div>

            <div className="tab-content">
                {activeTab === 'stream' && (
                    <div className="tab-pane stream-pane">
                        <div className="stream-chat-wrapper">
                            <Chat filterClassroomId={Number(classId)} />
                        </div>
                    </div>
                )}

                {activeTab === 'classwork' && (
                    <div className="tab-pane classwork-pane">
                        <div className="admin-class-grid single-column">
                            <div className="control-panel-card assignments-card">
                        <div className="card-custom-header">
                            <BookOpen size={20} />
                            <h3>Course Instances</h3>
                        </div>
                        <div className="assignments-list">
                            {classroom.course_assignments && classroom.course_assignments.length > 0 ? (
                                classroom.course_assignments.map(assign => (
                                    <div key={assign.id} className="assignment-item">
                                        <div className="assign-details">
                                            <span className="assign-id-lbl">Instance ID</span>
                                            <span className="assign-id-val">{assign.id}</span>
                                        </div>
                                        <div className="assign-details">
                                            <span className="assign-id-lbl">Course ID</span>
                                            <span className="assign-id-val badge-course">{assign.course_id || 'None'}</span>
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="empty-roster-msg">No course instances assigned.</div>
                            )}
                        </div>
                    </div>
                        </div>
                    </div>
                )}

                {activeTab === 'people' && (
                    <div className="tab-pane people-pane">
                        <div className="admin-class-grid single-column">
                            <div className="control-panel-card roster-card">
                    <div className="card-custom-header">
                        <div className="title-section">
                            <Users size={20} />
                            <h3>Student Roster</h3>
                        </div>
                        <input 
                            type="text" 
                            placeholder="Filter roster..." 
                            value={rosterSearchQuery}
                            onChange={(e) => setRosterSearchQuery(e.target.value)}
                            className="roster-search-input"
                        />
                    </div>

                    <div className="roster-list-container">
                        {filteredRoster.length > 0 ? (
                            <div className="roster-list">
                                {filteredRoster.map(student => (
                                    <div key={student.id} className="roster-item">
                                        <div className="student-info cursor-pointer" onClick={() => navigate(`/admin/users/${student.id}`)}>
                                            <SmartImage 
                                                src={student.profile_picture ? getApiUrl(`/user/profile_pictures/${student.profile_picture}`) : ''} 
                                                alt="" 
                                                className="avatar-tiny"
                                                fallbackType="avatar"
                                            />
                                            <div className="student-names">
                                                <span className="name">{student.nickname || student.username}</span>
                                                <span className="handle">@{student.username}</span>
                                            </div>
                                            <span className={`status-dot ${student.is_online ? 'online' : 'offline'}`} />
                                        </div>
                                        <button 
                                            type="button" 
                                            className="btn-action-sm danger unenroll-btn"
                                            onClick={() => handleUnenrollStudent(student.id)}
                                            disabled={formLoading}
                                        >
                                            Remove
                                        </button>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="empty-roster-msg">No students found.</div>
                        )}
                    </div>

                    {/* Enrollment form */}
                    <div className="enrollment-section">
                        <h4>Enroll New Student</h4>
                        <form onSubmit={handleEnrollStudent} className="enroll-form">
                            <div className="enroll-controls">
                                <select 
                                    value={selectedStudentId} 
                                    onChange={(e) => setSelectedStudentId(e.target.value)}
                                    className="student-enroll-select"
                                    required
                                >
                                    <option value="">-- Select Student --</option>
                                    {availableStudents.map(student => (
                                        <option key={student.id} value={student.id}>
                                            {student.nickname || student.username} (@{student.username})
                                        </option>
                                    ))}
                                </select>
                                <button 
                                    type="submit" 
                                    className="btn-action-sm primary enroll-btn"
                                    disabled={formLoading || !selectedStudentId}
                                >
                                    <Plus size={16} /> Enroll
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
                        </div>
                    </div>
                )}

                {activeTab === 'settings' && (
                    <div className="tab-pane settings-pane">
                        <div className="admin-class-grid single-column centered-column">
                            <div className="control-panel-card settings-card">
                        <div className="card-custom-header">
                            <Settings size={20} />
                            <h3>Classroom Settings</h3>
                        </div>

                        <form onSubmit={handleUpdateSettings} className="settings-form">
                            <div className="form-group">
                                <label>Classroom Name</label>
                                <input 
                                    type="text" 
                                    name="name" 
                                    defaultValue={classroom.name} 
                                    placeholder="e.g. Saturday coding"
                                    required 
                                />
                            </div>

                            <div className="form-group">
                                <label>Language</label>
                                <input 
                                    type="text" 
                                    name="language" 
                                    defaultValue={classroom.language} 
                                    placeholder="e.g. Python, Scratch"
                                    required 
                                />
                            </div>

                            <div className="form-group">
                                <label>Course ID</label>
                                <input 
                                    type="text" 
                                    name="course_id" 
                                    defaultValue={classroom.course_id || ''} 
                                    placeholder="e.g. Python_Level_1"
                                />
                            </div>

                            <div className="form-group">
                                <label>Web App / Project URL</label>
                                <input 
                                    type="url" 
                                    name="url" 
                                    defaultValue={classroom.url || ''} 
                                    placeholder="https://..."
                                    required
                                />
                            </div>

                            <button type="submit" className="btn-save" disabled={formLoading}>
                                {formLoading ? 'Saving...' : 'Save Settings'}
                            </button>
                        </form>
                    </div>
                            <div className="control-panel-card danger-zone-card">
                        <div className="card-custom-header">
                            <Trash2 size={20} />
                            <h3>Danger Zone</h3>
                        </div>
                        <p className="danger-zone-desc">Deleting a classroom removes the classroom instance. Students remain active users in the system but will be unlinked from this group.</p>
                        <button 
                            type="button" 
                            className="btn-danger"
                            onClick={handleDeleteClassroom}
                        >
                            Delete Classroom
                        </button>
                    </div>
                
                        </div>
                    </div>
                )}
            </div>
            <BulkConnectionCardsModal
                isOpen={activeModal === 'bulk_connection_cards'}
                onClose={() => setActiveModal(null)}
                classrooms={[classroom]}
                fetchClassrooms={fetchClassroomDetails}
                classroomCards={classroomCards}
                setClassroomCards={setClassroomCards}
                isFetchingCards={isFetchingCards}
                fetchClassroomCards={fetchClassroomCards}
            />
        </div>
    );
};

export default AdminClassDashboard;

